    content: 'শিশুদের দাঁত ওঠার সময়টি মা-বাবা এবং শিশু উভয়ের জন্যই বেশ কষ্টকর হতে পারে। এই সময়ে শিশুরা খিটখিটে হয়ে যায়, কান্নাকাটি করে এবং অনেক সময় পেটের সমস্যায় ভোগে। হোমিওপ্যাথি চিকিৎসায় দাঁত ওঠার কষ্ট লাঘবে চমৎকার কিছু ওষুধ রয়েছে।\n\n**ক্যামোমিলা (Chamomilla):** দাঁত ওঠার সময় যদি শিশু অত্যন্ত খিটখিটে হয়ে যায়, কিছুতেই শান্ত হতে চায় না, এবং কোলে চড়ে বেড়াতে চায়, তবে ক্যামোমিলা প্রধান ওষুধ। এই শিশুদের এক গাল লাল এবং অন্য গাল ফ্যাকাশে হতে দেখা যায়। তাদের পায়খানা সাধারণত সবুজ রঙের এবং দুর্গন্ধযুক্ত হয়।\n\n**ক্যালকেরিয়া কার্ব (Calcarea Carb):** যে সব শিশু দেখতে নাদুসনুদুস, মোটা এবং থলথলে, তাদের দাঁত উঠতে দেরি হলে ক্যালকেরিয়া কার্ব খুব ভালো কাজ করে। এই শিশুদের মাথায় প্রচুর ঘাম হয়, বিশেষ করে ঘুমের মধ্যে বালিশ ভিজে যায়। তারা ডিম খেতে খুব পছন্দ করে।\n\n**পডোফাইলাম (Podophyllum):** দাঁত ওঠার সময় যদি শিশুর ঘন ঘন পাতলা পায়খানা হয়, তবে পডোফাইলাম ব্যবহার করা যেতে পারে। এদের পায়খানা খুব দুর্গন্ধযুক্ত হয় এবং সকালে বেশি হয়। শিশু পায়খানার আগে ও পরে খুব দুর্বল হয়ে পড়ে।\n\n**ম্যাগনেশিয়া কার্ব (Magnesia Carb):** দাঁত ওঠার সময় শিশুদের হজমের গণ্ডগোল এবং টক গন্ধযুক্ত পায়খানা হলে এটি কার্যকরী। এই শিশুরা দুধ সহ্য করতে পারে না।\n\n**ঘরোয়া যত্ন ও পরামর্শ:**\nদাঁত ওঠার সময় শিশুদের মাড়িতে সুড়সুড়ি বা ব্যথা হতে পারে, তাই তারা হাতের কাছে যা পায় তাই কামড়াতে চায়। এই সময় তাদের পরিষ্কার ও নিরাপদ খেলনা বা টিথার দেওয়া উচিত। মাড়ি ম্যাসাজ করে দিলে শিশুরা আরাম পায়। পরিষ্কার সুতি কাপড় ঠান্ডা জলে ভিজিয়ে মাড়িতে আলতো করে ঘষে দেওয়া যেতে পারে। এই সময়ে শিশুর খাবারের প্রতি অরুচি দেখা দিতে পারে, তাই জোর করে না খাইয়ে অল্প অল্প করে বারবার তরল বা নরম খাবার দেওয়া উচিত। লক্ষন অনুযায়ী সঠিক হোমিওপ্যাথি ওষুধ প্রয়োগ করলে শিশুরা এই কঠিন সময়টি হাসিখুশিভাবে পার করতে পারে এবং তাদের দাঁত ওঠার প্রক্রিয়া সহজ হয়।',
